public static void main(String[] args) {
    try (Scanner sc = new Scanner(System.in)) {
        int N = sc.nextInt();
        int M = sc.nextInt();

        ArrayList<Integer> listA = new ArrayList<>();
        ArrayList<Integer> listB = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            listA.add(sc.nextInt());
        }

        for (int i = 0; i < M; i++) {
            listB.add(sc.nextInt());
        }

        ArrayList<Integer> combinedList = new ArrayList<>(listA);
        combinedList.addAll(listB);

        Collections.sort(combinedList);

        boolean found = false;
        for (int i = 0; i < combinedList.size() - 1; i++) {
            int current = combinedList.get(i);
            int next = combinedList.get(i + 1);
            if (listA.contains(current) && listA.contains(next)) {
                int indexCurrent = listA.indexOf(current);
                int indexNext = listA.indexOf(next);
                if (indexNext == indexCurrent + 1) {
                    System.out.println("Yes");
                    found = true;
                    break;
                }
            }
        }

        if (!found) {
            System.out.println("No");
        }
    }
}
